fn largest_power_of_two_le(n: i8) -> i8 {
    let mut power = 1;
    while power <= n {
        power *= 2;
    }
    power / 2
}

fn solve(n: i8) -> i8 {
    if n % 2 != 0 {
        // n is odd
        (n - 1) / 2
    } else {
        // n is even
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

